import { PeerActionType, UserData } from './peerTypes';
import { Dispatch } from 'redux';
import { PeerConnection } from '../../helpers/peer';
import { ConnectionState, DataType, PlayerAbility, PlayerActionType, PlayerAttack, PlayerChoice, PlayerEndTurn, PlayerMove, UserDetails } from '../../helpers/common';
import { addPlayerToLobby, attack, choice, endTurn, move, playerDisconnected, reportVersionMismatch, playerUseAbility } from '../connection/connectionActions';
import { matchesPendingChoice } from '../connection/choiceValidation';

type JsonObject = Record<string, unknown>;

function parseBody(body: string): JsonObject | undefined {
    try {
        const value = JSON.parse(body);
        return value !== null && typeof value === 'object' && !Array.isArray(value) ? value as JsonObject : undefined;
    } catch {
        return undefined;
    }
}

function isPlayerAction(value: JsonObject, peerId: string, actionType: PlayerActionType): boolean {
    return value.playerId === peerId && value.actionType === actionType;
}

function isUserDetails(value: JsonObject, peerId: string): value is JsonObject & UserDetails {
    return value.id === peerId && typeof value.userName === 'string' && typeof value.color === 'string'
        && (value.rejoinGameId === undefined || typeof value.rejoinGameId === 'string');
}

function isAttack(value: JsonObject, peerId: string): value is JsonObject & PlayerAttack {
    return isPlayerAction(value, peerId, PlayerActionType.playerAttack)
        && Array.isArray(value.targets) && value.targets.every(target => target !== null && typeof target === 'object' && typeof (target as JsonObject).id === 'string')
        && Array.isArray(value.damageRoll) && value.damageRoll.every(Number.isFinite) && Number.isFinite(value.modifiers);
}

function isMove(value: JsonObject, peerId: string): value is JsonObject & PlayerMove {
    return isPlayerAction(value, peerId, PlayerActionType.playerMove)
        && (value.moveRoll === undefined || Array.isArray(value.moveRoll) && value.moveRoll.every(Number.isFinite));
}

function isEndTurn(value: JsonObject, peerId: string): value is JsonObject & PlayerEndTurn {
    return isPlayerAction(value, peerId, PlayerActionType.playerEndTurn);
}

function isAbility(value: JsonObject, peerId: string): value is JsonObject & PlayerAbility {
    return isPlayerAction(value, peerId, PlayerActionType.playerAbility)
        && (value.targetId === undefined || typeof value.targetId === 'string')
        && (value.itemName === undefined || typeof value.itemName === 'string')
        && (value.roll === undefined || Number.isFinite(value.roll))
        && (value.skipCounterattack === undefined || typeof value.skipCounterattack === 'boolean');
}

function isChoice(value: JsonObject): value is JsonObject & PlayerChoice {
    const choice = value.choice;
    return value.actionType === PlayerActionType.playerChoice && typeof value.playerId === 'string'
        && (value.result === undefined || typeof value.result === 'string')
        && choice !== null && typeof choice === 'object'
        && typeof (choice as JsonObject).type === 'string' && typeof (choice as JsonObject).target === 'string'
        && (choice as JsonObject).card !== null && typeof (choice as JsonObject).card === 'object'
        && typeof ((choice as JsonObject).card as JsonObject).name === 'string'
        && typeof ((choice as JsonObject).card as JsonObject).drawDeck === 'string'
        && ((choice as JsonObject).value === undefined || typeof (choice as JsonObject).value === 'string');
}

export const startPeerSession = (id: string) => ({
    type: PeerActionType.PEER_SESSION_START, payload: id
});

export const stopPeerSession = () => ({
    type: PeerActionType.PEER_SESSION_STOP,
});

export const setLoading = (loading: boolean) => ({
    type: PeerActionType.PEER_LOADING, payload: loading
});

export const setUserData = (userData: UserData) => ({
    type: PeerActionType.PEER_SET_USER_DATA, payload: userData
});

export const startPeer: (previousId?: string) => (dispatch: Dispatch, getState: () => { connection: ConnectionState }) => Promise<string | undefined>
    = (previousId?: string) => (async (dispatch, getState) => {
        dispatch(setLoading(true));

        try {
            const id = await PeerConnection.startPeerSession(previousId);
            PeerConnection.onIncomingConnection((conn) => {
                const peerId = conn.peer;
                PeerConnection.onConnectionDisconnected(peerId, () => {
                    dispatch(playerDisconnected(peerId));
                });

                PeerConnection.onConnectionReceiveData(peerId, async (data) => {
                    //Receive data from users
                    switch (data.dataType) {
                        case DataType.VersionMismatch: {
                            const details = parseBody(data.body);
                            dispatch(reportVersionMismatch({
                                peerId,
                                remoteVersion: data.appVersion ?? (typeof details?.receivedVersion === 'string' ? details.receivedVersion : undefined)
                            }));
                            return;
                        }
                        case DataType.UserDetails: {
                            const user = parseBody(data.body);
                            if (!user || !isUserDetails(user, peerId)) return;
                            const gameState = getState().connection.gameState;
                            if (gameState.started && user.rejoinGameId === undefined) return;
                            if (user.rejoinGameId !== undefined && (!gameState.started || gameState.gameEnded
                                || gameState.gameId !== user.rejoinGameId
                                || !gameState.lobby.playerList.some(player => player.user.id === user.id
                                    && (!player.user.isBot || player.user.replacedPlayerName !== undefined)))) {
                                void PeerConnection.sendConnection(peerId, { dataType: DataType.GameRecoveryRejected, body: '' });
                                return;
                            }
                            dispatch(addPlayerToLobby(user));
                            return;
                        }
                        case DataType.PlayerAttack: {
                            const event = parseBody(data.body);
                            if (event && isAttack(event, peerId)) dispatch(attack(event));
                            return;
                        }
                        case DataType.PlayerChoice: {
                            const event = parseBody(data.body);
                            if (event && isChoice(event) && matchesPendingChoice(getState().connection.pendingChoice, event)
                                && getState().connection.pendingChoice?.recipientId === peerId) dispatch(choice(event));
                            return;
                        }
                        case DataType.PlayerMove: {
                            const event = parseBody(data.body);
                            if (event && isMove(event, peerId)) dispatch(move(event));
                            return;
                        }
                        case DataType.PlayerEndTurn: {
                            const event = parseBody(data.body);
                            if (event && isEndTurn(event, peerId)) dispatch(endTurn(event));
                            return;
                        }
                        case DataType.PlayerAbility: {
                            const event = parseBody(data.body);
                            if (event && isAbility(event, peerId)) dispatch(playerUseAbility(event));
                            return;
                        }
                        case DataType.PlayerEvent:
                            return;
                    }
                });
            });

            dispatch(startPeerSession(id));
            dispatch(setLoading(false));
            return id;
        } catch (e) {
            console.log(e);
            dispatch(setLoading(false));
            return undefined;
        }
    });
